DROP POLICY IF EXISTS "invoices_company_select" ON public.invoices;
DROP POLICY IF EXISTS "invoices_company_update" ON public.invoices;
DROP POLICY IF EXISTS "invoices_company_write" ON public.invoices;
DROP POLICY IF EXISTS "invoice_items_company_select" ON public.invoice_items;
DROP POLICY IF EXISTS "invoice_items_company_write" ON public.invoice_items;
DROP POLICY IF EXISTS "Company isolation - sale_items" ON public.sale_items;
CREATE POLICY "sale_items_branch_select" ON public.sale_items FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.sales s WHERE s.id=sale_items.sale_id AND s.company_id=public.get_my_company_id() AND public.user_has_branch_access(s.branch_id)));
CREATE POLICY "sale_items_no_direct_insert" ON public.sale_items FOR INSERT TO authenticated WITH CHECK (false);
CREATE POLICY "sale_items_no_direct_update" ON public.sale_items FOR UPDATE TO authenticated USING (false) WITH CHECK (false);
CREATE POLICY "sale_items_no_direct_delete" ON public.sale_items FOR DELETE TO authenticated USING (false);
DROP POLICY IF EXISTS "repair_parts_usage_select" ON public.repair_parts_usage;
CREATE POLICY "repair_parts_usage_branch_select" ON public.repair_parts_usage FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.repairs r WHERE r.id=repair_parts_usage.repair_id AND r.company_id=public.get_my_company_id() AND public.user_has_branch_access(r.branch_id)));
DROP POLICY IF EXISTS "Users can view company repair payments" ON public.repair_payments;
CREATE POLICY "repair_payments_branch_select" ON public.repair_payments FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.repairs r WHERE r.id=repair_payments.repair_id AND r.company_id=public.get_my_company_id() AND public.user_has_branch_access(r.branch_id)));
DROP POLICY IF EXISTS "Company isolation - repair_tickets" ON public.repair_tickets;
CREATE POLICY "repair_tickets_branch_select" ON public.repair_tickets FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.repairs r WHERE r.id=repair_tickets.repair_id AND r.company_id=public.get_my_company_id() AND public.user_has_branch_access(r.branch_id)));
CREATE POLICY "repair_tickets_no_direct_insert" ON public.repair_tickets FOR INSERT TO authenticated WITH CHECK (false);
CREATE POLICY "repair_tickets_no_direct_update" ON public.repair_tickets FOR UPDATE TO authenticated USING (false) WITH CHECK (false);
CREATE POLICY "repair_tickets_no_direct_delete" ON public.repair_tickets FOR DELETE TO authenticated USING (false);
DROP POLICY IF EXISTS "inventory_stock_movements_select_company" ON public.inventory_stock_movements;
CREATE POLICY "inventory_stock_movements_branch_select" ON public.inventory_stock_movements FOR SELECT TO authenticated USING (company_id=public.get_my_company_id() AND EXISTS (SELECT 1 FROM public.inventory i WHERE i.id=inventory_stock_movements.inventory_id AND (i.branch_id IS NULL OR public.user_has_branch_access(i.branch_id))));
